    15	/**
    16	  * English implementation note.
    17	  * English implementation note.
    18	  * English implementation note.
    19	 */
    20	public class UserManager {
    21	
    22	    private static final int MAX_TENTATIVI = 5;
    23	    private static final int MINUTI_BLOCCO = 15;
    24	
    25	    /** English implementation note. */
    26	    private static final String REGEX_EMAIL_ISTITUZIONALE = "^[^@\\s]+@([^@\\s]+\\.)*unina\\.it$";
    27	
    28	    /** English implementation note. */
    29	    private static final String REGEX_STUDENT_NUMBER = "[A-Z]\\d{8}";
    30	
    31	    private final UserRegistry userRegistry = UserRegistry.getInstance();
    32	
    33	    private static UserManager instance;
    34	
    35	    private UserManager() {}
    36	
    37	    public static UserManager getInstance() {
    38	        if (instance == null) {
    39	            instance = new UserManager();
    40	        }
    41	        return instance;
    42	    }
    43	
    44	    /** English implementation note. */
    45	    private void require(boolean condition, String message) {
    46	        if (!condition) {
    47	            throw new IllegalArgumentException(message);
    48	        }
    49	    }
    50	
    51	    /** English implementation note. */
    52	    private void validate(String role, String name, String password) {
    53	        // English implementation note.
    54	        require(role != null && !role.isEmpty() && isValidRole(role), "A valid role is required.");
    55	        require(name != null && !name.isEmpty(), "First name is required.");
    56	        require(password != null && password.length() >= 8, "Password must contain at least 8 characters.");
    57	        require(password.length() <= 32, "Password cannot exceed 32 characters.");
    58	    }
    59	
    60	    // ------------------------------------------------------------------ UC1
    61	    /**
    62	      * English implementation note.
    63	      * English implementation note.
    64	     */
    65	    public UserDTO register(String role, String name, String surname,
    66	                                String email, String password, String identifier) {
    67	        validate(role, name, password);
    68	
    69	        // English implementation note.
    70	        boolean student = "Student".equalsIgnoreCase(role);
    71	        if (student) {
    72	            validateStudent(name, surname, email, identifier);
    73	        } else {
    74	            validateLibrarian(name, surname, email, identifier);
    75	        }
    76	
    77	        if (userRegistry.institutionalEmailExists(email)) {
    78	            throw new IllegalArgumentException("Email is already associated with an account.");
    79	        }
    80	
    81	        boolean identifierGiaUsato = student
    82	                ? userRegistry.findStudentByStudentNumber(identifier) != null
    83	                : userRegistry.findLibrarianByCode(identifier) != null;
    84	        if (identifierGiaUsato) {
    85	            throw new IllegalArgumentException("Identifier is already in use.");
    86	        }
    87	
    88	        // English implementation note.
    89	        UserFactory factory = student ? new StudentFactory() : new LibrarianFactory();
    90	        User newUser = factory.createUser(name, surname, email, password, identifier);
    91	
    92	        boolean success = userRegistry.registerUser(newUser);
    93	        if (!success){
    94	            throw new RuntimeException("Server error: the user could not be saved. Please try again.");
    95	        }
    96	        return toDTO(newUser);
    97	    }
    98	
    99	    // ------------------------------------------------------------------ UC2
   100	    /**
   101	      * English implementation note.
   102	      * English implementation note.
   103	      * English implementation note.
   104	      * English implementation note.
   105	     */
   106	    public UserDTO authenticate(String email, String password) {
   107	        validateCredentialFormat(email, password);
   108	
   109	        User user = userRegistry.findUserByEmail(email);
   110	
   111	        if (user == null) {
   112	            throw new SecurityException("Invalid credentials or user does not exist.");
   113	        }
   114	        if (user.isBloccato()) {
   115	            throw new SecurityException("Account locked after too many failed attempts. Try again in "
   116	                    + MINUTI_BLOCCO + " minutes.");
   117	        }
   118	
   119	        if (!verifyCredentials(user, password)) {
   120	            incrementaTentativi(user);
   121	            boolean appenaBloccato = user.getFailedAttempts() >= MAX_TENTATIVI;
   122	            if (appenaBloccato) {
   123	                bloccaAccountTemporaneamente(user, MINUTI_BLOCCO);
   124	            }
   125	            userRegistry.update(user);
   126	            if (appenaBloccato) {
   127	                throw new SecurityException("Invalid credentials. Account locked for " + MINUTI_BLOCCO
   128	                        + " minutes after too many failed attempts.");
   129	            }
   130	            throw new SecurityException("Invalid credentials or user does not exist.");
   131	        }
   132	
   133	        resetTentativi(user);
   134	        userRegistry.update(user);
   135	        return toDTO(user);
   136	    }
   137	
   138	    /**
   139	      * English implementation note.
   140	      * English implementation note.
   141	      * English implementation note.
   142	     */
   143	    private void validateCredentialFormat(String email, String password) {
   144	        require(email != null && !email.isEmpty(), "Email is required.");
   145	        require(isEmailWellFormed(email), "Invalid email format.");
   146	        require(password != null && !password.isEmpty(), "Password is required.");
   147	        require(password.length() >= 8, "Password must contain at least 8 characters.");
   148	        require(password.length() <= 32, "Invalid password format.");
   149	    }
   150	
   151	    /** English implementation note. */
   152	    private boolean isEmailWellFormed(String email) {
   153	        return email.length() < 255 && email.matches(REGEX_EMAIL_ISTITUZIONALE);
   154	    }
   155	
   156	    // -------------------------------------------------------------- UC8 (profile)
   157	    /**
   158	      * English implementation note.
   159	     */
   160	    public UserDTO visualizzaProfilo(Long studentId) {
   161	        Student student = userRegistry.findStudentById(studentId);
   162	        if (student == null) {
   163	            throw new IllegalArgumentException("Student not found");
   164	        }
   165	        return toDTO(student);
   166	    }
   167	
   168	    // ------------------------------------------------------------------ helper privati
   169	    private boolean isValidRole(String role) {
   170	        return "Student".equalsIgnoreCase(role) || "Librarian".equalsIgnoreCase(role);
   171	    }
   172	
   173	    private void validateStudent(String name, String surname, String email, String studentNumber) {
   174	        validateNameAndSurname(name, surname);
   175	        validateEmail(email);
   176	        validateIdentifier(studentNumber, "studentNumber");
   177	        if (!studentNumber.matches(REGEX_STUDENT_NUMBER)) {
   178	            throw new IllegalArgumentException(
   179	                    "Unrecognized identifier format: the student ID must be an uppercase letter followed by 8 digits (e.g. N86001234).");
   180	        }
   181	    }
   182	
   183	    private void validateLibrarian(String name, String surname, String email, String code) {
   184	        validateNameAndSurname(name, surname);
   185	        validateEmail(email);
   186	        validateIdentifier(code, "code identifier");
   187	    }
   188	
   189	    private void validateNameAndSurname(String name, String surname) {
   190	        if (!name.matches("\\p{L}{1,20}")) {
   191	            throw new IllegalArgumentException("Invalid first-name format (letters only, max 20 characters).");
   192	        }
   193	        if (surname == null || surname.isEmpty()) {
   194	            throw new IllegalArgumentException("Last name is required.");
   195	        }
   196	        if (!surname.matches("\\p{L}{1,20}")) {
   197	            throw new IllegalArgumentException("Invalid last-name format (letters only, max 20 characters).");
   198	        }
   199	    }
   200	
   201	    private void validateEmail(String email) {
   202	        if (email == null || email.isEmpty()) {
   203	            throw new IllegalArgumentException("Email is required.");
   204	        }
   205	        // English implementation note.
   206	        if (email.length() >= 255) {
   207	            throw new IllegalArgumentException("Email is too long (max 255 characters).");
   208	        }
   209	        if (!isEmailWellFormed(email)) {
   210	            throw new IllegalArgumentException("Invalid email format.");
   211	        }
   212	    }
   213	
   214	    private void validateIdentifier(String identifier, String label) {
   215	        if (identifier == null || identifier.isEmpty()) {
   216	            throw new IllegalArgumentException("Identifier is required.");
   217	        }
   218	        if (!identifier.matches("[A-Za-z0-9]+")) {
   219	            throw new IllegalArgumentException("Invalid " + label + " format.");
   220	        }
   221	    }
   222	
   223	    private boolean verifyCredentials(User user, String password) {
   224	        return password != null && password.equals(user.getPassword());
   225	    }
   226	
   227	    private void incrementaTentativi(User user) {
   228	        user.setFailedAttempts(user.getFailedAttempts() + 1);
   229	    }
   230	
   231	    private void bloccaAccountTemporaneamente(User user, int durataMinuti) {
   232	        user.setLockedUntilA(LocalDateTime.now(ZoneId.of("Europe/Rome")).plusMinutes(durataMinuti));
   233	        user.setFailedAttempts(0);
   234	    }
   235	
   236	    private void resetTentativi(User user) {
   237	        user.setFailedAttempts(0);
   238	        user.setLockedUntilA(null);
   239	    }
   240	
   241	    /** English implementation note. */
   242	    private UserDTO toDTO(User user) {
   243	        UserDTO dto = new UserDTO();
   244	        dto.setId(user.getId());
   245	        dto.setName(user.getName());
   246	        dto.setSurname(user.getSurname());
   247	        dto.setInstitutionalEmail(user.getInstitutionalEmail());
   248	        if (user instanceof Student s) {
   249	            dto.setRole("Student");
   250	            dto.setIdentifier(s.getStudentNumber());
   251	            dto.setTotalVisitCount(s.getTotalVisitCount());
   252	        } else if (user instanceof Librarian b) {
   253	            dto.setRole("Librarian");
   254	            dto.setIdentifier(b.getInternalIdentifierCode());
   255	        }
   256	        return dto;
   257	    }
   258	}
