#!/usr/bin/env python3
"""Phases 6-8: reconciliation, views, notation, validation, reports."""
import json, os, re, hashlib, subprocess, sys

HERE = os.path.dirname(__file__)
R = "/Users/miryalasathvika/t2v-subjects/skill-agent/IS-reg-L3/Progetto-IS-main-English"
OUT = R + "/task2view-out/IS-reg-L3"
M = json.load(open(os.path.join(HERE, "model.json")))
model, FR = M["model"], M["FR"]
Q = json.load(open(OUT + "/architectural_questions.json"))
plan = json.load(open(OUT + "/view_plan.json"))
profile = json.load(open(OUT + "/stakeholder_profile.json"))
claims, elements, relations = model["claims"], model["elements"], model["relations"]
steps = model["scenarios"]["scn:register-user"]["steps"]

V1, V2, V3 = "V1-decomposition", "V2-client-server", "V3-sequence"
LAYER_NAME = {"presentation": "Presentation", "application": "Application", "domain": "Domain", "persistence": "Persistence"}
LAYER_ORDER = ["presentation", "application", "domain", "persistence"]


def dump(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w") as f:
        json.dump(obj, f, indent=2, ensure_ascii=False)


def alias(i):
    a = "e_" + re.sub(r"[^A-Za-z0-9]", "_", i)
    if a != "e_" + i:
        a += "_" + hashlib.md5(i.encode()).hexdigest()[:4]
    return a


def wrap(text, w=44):
    words, lines, cur = text.split(), [], ""
    for wd in words:
        if len(cur) + len(wd) + 1 > w and cur:
            lines.append(cur)
            cur = wd
        else:
            cur = (cur + " " + wd).strip()
    lines.append(cur)
    return ("\\n  ").join(lines)


def trace_for(eid):
    files, syms = [], []
    e = elements[eid]
    for cid in e["claims"]:
        for ci in claims[cid]["evidence"]:
            if ci["file"] not in files:
                files.append(ci["file"])
    for s in e["realized_by"]:
        syms.append(s)
    return {"element": eid, "name": e["name"], "files": files, "symbols": syms}


def mk_el(eid, group=False, parent=None, kind=None):
    e = elements[eid]
    return {"id": eid, "kind": kind or e["kind"], "name": e["name"], "stereotype": e["layer"], "parent": parent,
            "responsibilities": [r["text"] for r in e["responsibilities"]], "attributes": [], "realized_by": e["realized_by"],
            "support": e["support"], "group": False}


def mk_group(layer):
    return {"id": f"group:layer:{layer}", "kind": "layer", "name": LAYER_NAME[layer], "stereotype": None, "parent": None,
            "responsibilities": [], "attributes": [], "realized_by": [], "support": "observed", "group": True}


comps = [eid for eid, e in elements.items() if e["kind"] == "component"]
# presentation first, then by layer order; stable inside a layer (claim order)
comps.sort(key=lambda x: LAYER_ORDER.index(elements[x]["layer"]))
layers_used = [l for l in LAYER_ORDER if any(elements[c]["layer"] == l for c in comps)]
V_PROP = {
    V1: ("decomposition", "Decomposition Style", "2.1 Decomposition Style", "uml-package", 15),
    V2: ("client-server", "Client-Server", "4.3.1 Client-Server Style", "uml-component", 15),
    V3: ("sequence", "Sequence", "8.3.1 Notations for Capturing Traces (sequence diagrams)", "uml-sequence", 12),
}
qs = {v: [q for q in Q if q["view_id"] == v] for v in V_PROP}
views = {}

# ----------------------------------------------------------------------------- V1
els = [mk_group(l) for l in layers_used] + [mk_el(c, parent=f"group:layer:{elements[c]['layer']}") for c in comps]
rels = [{"id": r["id"], "kind": "is-part-of", "source": r["source"], "target": r["target"], "label": None, "multiplicity": None,
         "support": r["support"]} for r in relations.values() if r["kind"] == "is-part-of"]
views[V1] = {"els": els, "rels": rels, "inter": [], "frags": [], "overflow": [],
             "title": "Decomposition view — user registration functionality",
             "purpose": "Shows the main components of user registration, grouped by layer, with the responsibility each takes in the registration request, validation, role-specific data, uniqueness checks and persistence.",
             "limitations": ["Layer groups are containers and are not counted toward the 15-element cap; the 14 drawn components fit the cap.",
                             "is-part-of is drawn as nesting of each component in its layer group (the relations are listed in view.json).",
                             "UserDTO (returned by AuthenticationController, LibraryFacade and UserManager) is not an element of the evidence model and is not drawn."],
             "gaps": []}

# ----------------------------------------------------------------------------- V2
DRAWN2 = comps + ["datastore:reservationsdb"]
els = [mk_group(l) for l in layers_used]
for c in comps:
    els.append(mk_el(c, parent=f"group:layer:{elements[c]['layer']}"))
els.append(mk_el("datastore:reservationsdb"))
rels2 = [{"id": r["id"], "kind": r["kind"], "source": r["source"], "target": r["target"], "label": r["label"], "multiplicity": None, "support": r["support"]}
         for r in relations.values() if r["kind"] in ("uses", "reads", "writes") and r["source"] in DRAWN2 and r["target"] in DRAWN2]
views[V2] = {"els": els, "rels": rels2, "inter": [], "frags": [], "overflow": [],
             "title": "Client-Server view — user registration functionality",
             "purpose": "Shows which components work together to serve a registration request, who calls whom, the operations they use, and where the data is read and written.",
             "limitations": ["RestExceptionHandler has no relation: Spring binds it through @RestControllerAdvice/@ExceptionHandler, so no registration component depends on it statically. Its role in failure paths is shown in V3.",
                             "Generalization (StudentFactory/LibrarianFactory implement UserFactory; Student/Librarian extend User) is not a Client-Server relation kind and is not drawn; it is in the evidence model.",
                             "Swing Registration calls LibraryFacade in-process; the only request-reply connector (HTTP from registration.html to AuthenticationController) is shown in V3.",
                             "The 15-element cap is reached (14 components and the datastore); layer groups are containers and not counted.",
                             "UserDTO is not drawn (not an element of the evidence model)."],
             "gaps": []}

# ----------------------------------------------------------------------------- V3
seen = []
for s in steps:
    for k in (s["source"], s["target"]):
        if k not in seen:
            seen.append(k)
els = []
for k in seen:
    e = elements[k]
    els.append({"id": k, "kind": "actor" if e["kind"] == "actor" else "lifeline", "name": e["name"], "stereotype": e["layer"], "parent": None,
                "responsibilities": [], "attributes": [], "realized_by": e["realized_by"], "support": e["support"], "group": False})
inter = [{"order": s["order"], "source": s["source"], "target": s["target"], "message": s["message"], "kind": s["kind"], "fragment": s["fragment"]} for s in steps]
frags = model["scenarios"]["scn:register-user"]["fragments"]
views[V3] = {"els": els, "rels": [], "inter": inter, "frags": frags, "overflow": [],
             "title": "Sequence view — register user (REST path, valid and invalid data)",
             "purpose": "Shows the order of calls for a registration request from the web client, with the failure paths for invalid data, an existing email, an identifier already in use and a failed save.",
             "limitations": ["One scenario only: registration through POST /api/auth/register. The Swing client calls LibraryFacade.register directly and shows errors with showError(ex.getMessage()); it is an alternative entry and is not drawn.",
                             "The returns '400 {error}', 'UserDTO' and the RuntimeException of a failed save are inferred from the controller/handler/manager code (no direct call), so they have support 'inferred'.",
                             "RestExceptionHandler handles IllegalArgumentException, IllegalStateException and SecurityException only: the RuntimeException of a failed save has no handler in the code, so the HTTP response of that path is not evidenced.",
                             "Role alternatives (Student / Librarian) are drawn as alt/else pairs of the fragments recorded separately in the evidence model.",
                             "The layered overlay is shown as stereotypes on the lifelines (lifelines follow first appearance, so layer boxes cannot be contiguous)."],
             "gaps": []}

# ----------------------------------------------------------------------------- Phase 6 (coverage + decision)
def drawn_claims(v):
    V = views[v]
    ids = set()
    elids = {e["id"] for e in V["els"]}
    relids = {(r["source"], r["target"], r["kind"]) for r in V["rels"]}
    stepset = {(i["order"]) for i in V["inter"]}
    for c in claims.values():
        if c["kind"] == "element":
            eid = ("cmp:" + c["symbol"]) if c["symbol"] else (("actor:registration-html") if c["element_kind"] == "actor" else "datastore:" + c["name"])
            if eid in elids:
                ids.add(c["id"])
        elif c["kind"] == "relation":
            s = c["source"] if c["source"].startswith(("actor:", "datastore:")) else "cmp:" + c["source"]
            t = c["target"] if c["target"].startswith(("actor:", "datastore:")) else "cmp:" + c["target"]
            if (s, t, c["relation"]) in relids:
                ids.add(c["id"])
        elif c["kind"] == "interaction" and c["order"] in stepset and v == V3:
            ids.add(c["id"])
    return ids


recon = {}
cover = {}
for v in V_PROP:
    drawn = drawn_claims(v)
    cov = []
    for q in qs[v]:
        ans = [c["id"] for c in claims.values() if q["id"] in c["question_ids"]]
        shown = [c for c in ans if c in drawn]
        status = "supported" if shown else ("partial" if ans else "unsupported")
        note = "" if shown else ("claims exist but none is drawn" if ans else "no evidence")
        cov.append({"question": q["id"], "status": status, "claims": shown or ans, "note": note})
    cover[v] = cov
    uns = [c["question"] for c in cov if c["status"] == "unsupported"]
    nonempty = len(views[v]["els"]) > 0
    if not nonempty:
        dec, why = "gap", "view draws nothing"
    elif views[v]["overflow"]:
        dec, why = "simplify", "view overflows its cap"
    elif plan["views"][list(V_PROP).index(v)]["evidence_gap"]:
        dec, why = "gap", "evidence gap"
    else:
        dec, why = "confirm", "all assigned questions have evidence in the view"
    recon[v] = {"view_id": v, "decision": dec, "reason": why, "coverage": cov, "unsupported_questions": uns}
dump(OUT + "/reconciliation.json", recon)

# ----------------------------------------------------------------------------- Phase 7: notation
def comp_label(e):
    lines = [e["name"], "--"] + ["- " + wrap(r) for r in e["responsibilities"]]
    return "\\n".join(lines)


def puml_structure(v):
    V = views[v]
    L = ["@startuml", f"title {V['title']}", "skinparam componentStyle uml2", "skinparam shadowing false", "left to right direction"]
    byparent = {}
    for e in V["els"]:
        if e["group"]:
            byparent.setdefault(e["id"], [])
    for e in V["els"]:
        if not e["group"] and e["parent"]:
            byparent[e["parent"]].append(e)
    for g in [x for x in V["els"] if x["group"]]:
        L.append(f'package "{g["name"]}" as {alias(g["id"])} <<layer>> {{')
        for e in byparent[g["id"]]:
            L.append(f'  component "{comp_label(e)}" as {alias(e["id"])} <<{e["stereotype"]}>>')
        L.append("}")
    for e in V["els"]:
        if not e["group"] and not e["parent"]:
            if e["kind"] == "datastore":
                L.append(f'database "{e["name"]}" as {alias(e["id"])}')
    if v == V1:
        L.append("' is-part-of is drawn as nesting of each component in its layer package")
    for r in V["rels"]:
        if r["kind"] == "is-part-of":
            continue
        lab = r["label"] or ""
        if r["kind"] in ("reads", "writes"):
            lab = f"<<{r['kind']}>> {lab}"
        L.append(f'{alias(r["source"])} --> {alias(r["target"])} : {lab}'.rstrip(" :") if not lab else f'{alias(r["source"])} --> {alias(r["target"])} : {lab}')
    L.append("@enduml")
    return "\n".join(L) + "\n"


def puml_sequence(v):
    V = views[v]
    L = ["@startuml", f"title {V['title']}", "skinparam shadowing false", "autonumber off"]
    for e in V["els"]:
        if e["kind"] == "actor":
            L.append(f'actor "{e["name"]}" as {alias(e["id"])}')
        else:
            L.append(f'participant "{e["name"]}" as {alias(e["id"])} <<{e["stereotype"]}>>')
    cur = None
    prev_guard = None
    items = V["inter"]
    open_frag = None
    for i, s in enumerate(items):
        f = s["fragment"]
        if f != open_frag:
            if open_frag:
                prev_guard_f = FR[open_frag]["guard"]
            nxt_guard = FR[f]["guard"] if f else None
            if open_frag and f and FR[open_frag]["guard"] == "role is Student" and nxt_guard == "role is Librarian":
                L.append(f"else {nxt_guard}")
            else:
                if open_frag:
                    L.append("end")
                if f:
                    L.append(f"alt {nxt_guard}")
            open_frag = f
        arrow = "-->" if s["kind"] == "return" else "->"
        L.append(f'{"  " if f else ""}{alias(s["source"])} {arrow} {alias(s["target"])} : {s["order"]}. {s["message"]}')
    if open_frag:
        L.append("end")
    L.append("@enduml")
    return "\n".join(L) + "\n"


files_puml = {}
for v in V_PROP:
    src = puml_sequence(v) if v == V3 else puml_structure(v)
    files_puml[v] = src
    os.makedirs(f"{OUT}/{v}", exist_ok=True)
    open(f"{OUT}/{v}/view.puml", "w").write(src)

# ----------------------------------------------------------------------------- Phase 8: validation
def syntax_ok(src):
    try:
        p = subprocess.run(["plantuml", "-syntax"], input=src, capture_output=True, text=True, timeout=120)
        out = (p.stdout + p.stderr).strip()
        return ("ERROR" not in out.upper()), out.replace("\n", " | ")[:200]
    except Exception as ex:
        return None, str(ex)


ELK = {V1: ("module", "component"), V2: ("component", "interface", "datastore", "external_system"), V3: ("actor", "lifeline")}
RLK = {V1: ("is-part-of",), V2: ("request-reply", "uses", "reads", "writes"), V3: ("message", "return")}
report = {}
for v in V_PROP:
    V = views[v]
    cons, faith, repair = [], [], []
    ok, msg = syntax_ok(files_puml[v])
    notation = {"status": "pass" if ok else ("fail" if ok is False else "not-compiled"), "language": "plantuml", "approximated": v == V3,
                "model_kind_matches": True, "compiler_output": msg}
    errors = 0
    nongroup = [e for e in V["els"] if not e["group"]]
    for e in nongroup:
        if e["kind"] not in ELK[v]:
            cons.append({"constraint": "element_kind_allowed", "severity": "error", "mark": e["id"], "message": f"kind {e['kind']} not allowed"}); errors += 1
    for r in V["rels"]:
        if r["kind"] not in RLK[v]:
            cons.append({"constraint": "relation_kind_allowed", "severity": "error", "mark": r["id"], "message": f"kind {r['kind']} not allowed"}); errors += 1
    if len(nongroup) > V_PROP[v][4]:
        cons.append({"constraint": "max_elements", "severity": "error", "mark": v, "message": "over cap"}); errors += 1
    ids = {e["id"] for e in V["els"]}
    for e in V["els"]:
        if e["parent"] and e["parent"] not in ids:
            cons.append({"constraint": "nesting_well_formed", "severity": "error", "mark": e["id"], "message": "missing parent"}); errors += 1
    warn = 0
    if v != V3:
        for e in nongroup:
            if e["kind"] == "component" and not e["responsibilities"]:
                cons.append({"constraint": "component_has_responsibility", "severity": "warning", "mark": e["id"], "message": f"{e['name']} shows no responsibility"}); warn += 1
        inrel = set()
        for r in V["rels"]:
            inrel |= {r["source"], r["target"]}
        for e in nongroup:
            if e["id"] not in inrel:
                cons.append({"constraint": "no_isolated_element", "severity": "warning", "mark": e["id"], "message": f"{e['name']} takes part in no relation"}); warn += 1
    else:
        orders = [i["order"] for i in V["inter"]]
        if orders != sorted(orders) or len(set(orders)) != len(orders):
            cons.append({"constraint": "messages_ordered", "severity": "error", "mark": v, "message": "order not total"}); errors += 1
        for i in V["inter"]:
            cl = [c for c in claims.values() if c["kind"] == "interaction" and c["order"] == i["order"]]
            if not cl:
                cons.append({"constraint": "message_backed_by_call_evidence", "severity": "error", "mark": str(i["order"]), "message": "no claim"}); errors += 1
            elif cl[0]["support"] == "inferred":
                cons.append({"constraint": "message_backed_by_call_evidence", "severity": "warning", "mark": str(i["order"]),
                             "message": f"step {i['order']} ({i['message']}) is a return/exception flow with inferred support, cited code is in the callee"}); warn += 1
    # faithfulness
    for e in V["els"]:
        if e["group"]:
            continue
        me = elements.get(e["id"])
        if not me:
            faith.append({"check": "element in evidence model", "mark": e["id"], "message": "missing"}); errors += 1
        elif me["name"] != e["name"]:
            faith.append({"check": "names unchanged", "mark": e["id"], "message": "renamed"}); errors += 1
    syms = [s for e in nongroup for s in e["realized_by"]]
    if len(syms) != len(set(syms)) or len({e["id"] for e in nongroup}) != len(nongroup):
        faith.append({"check": "no element or symbol drawn twice", "mark": v, "message": "duplicate"}); errors += 1
    for e in nongroup:
        if elements[e["id"]]["support"] != "observed":
            faith.append({"check": "not weakly supported", "mark": e["id"], "message": "element support is not observed"}); errors += 1
    if v == V3:
        stepids = {s["order"] for s in steps}
        for i in V["inter"]:
            if i["order"] not in stepids:
                faith.append({"check": "interaction is a recovered step", "mark": str(i["order"]), "message": "not in scenario"}); errors += 1
    else:
        relids = set(relations)
        for r in V["rels"]:
            if r["id"] not in relids:
                faith.append({"check": "relation in evidence model", "mark": r["id"], "message": "missing"}); errors += 1
    covs = cover[v]
    if len(nongroup) >= 2 and not (V["rels"] or V["inter"]):
        errors += 1
    limits = bool(V["limitations"]) or bool(V["gaps"])
    nonsup = any(c["status"] != "supported" for c in covs)
    if notation["status"] != "pass":
        errors += 1 if notation["status"] == "fail" else 0
    verdict = "fail" if errors else ("pass_with_limitations" if (limits or warn or nonsup) else "pass")
    report[v] = {"view_id": v, "verdict": verdict, "notation": notation, "constraints": cons, "faithfulness": faith, "coverage": covs,
                 "task_fit": {"status": "not-run", "model": None, "rubric": "v1", "independent": None, "scores": {}, "summary": "a different model must judge"},
                 "errors": errors, "warnings": warn, "repair_marks": repair}
dump(OUT + "/validation_report.json", report)

# ----------------------------------------------------------------------------- write views
vs_views = []
for v in V_PROP:
    V = views[v]
    vp, name, ref, mk, cap = V_PROP[v]
    tr = [trace_for(e["id"]) for e in V["els"] if not e["group"]]
    obj = {"id": v, "viewpoint_id": vp, "viewpoint_name": name, "vb_ref": ref, "model_kind": mk, "title": V["title"], "purpose": V["purpose"],
           "detail_level": "detailed", "max_elements": cap, "addresses": [q["id"] for q in qs[v]], "overlays": ["layered"],
           "scenario": "scn:register-user" if v == V3 else None, "elements": V["els"], "relations": V["rels"], "interactions": V["inter"],
           "fragments": V["frags"], "traceability": tr, "limitations": V["limitations"], "gaps": V["gaps"], "overflow": V["overflow"]}
    dump(f"{OUT}/{v}/view.json", obj)
    vs_views.append(obj)
dump(f"{OUT}/{V3}/render_notes.json", [{"view": V3, "note": "Consecutive fragments 'role is Student' / 'role is Librarian' (alt2/alt3, alt6/alt7, alt9/alt10) are drawn as one PlantUML alt ... else ... end block; the evidence model keeps them as separate alt fragments."}])

# correspondences
corr = []
for c in comps + ["datastore:reservationsdb", "actor:registration-html"]:
    present = [f"{v}:{c}" for v in V_PROP if any(e["id"] == c for e in views[v]["els"])]
    if len(present) > 1:
        corr.append({"rule": "same-element", "elements": present})
model_out = {k: v for k, v in model.items()}
model_out["correspondences"] = [{"rule": "same-element", "elements": c["elements"], "note": ""} for c in corr]
dump(OUT + "/evidence_model.json", model_out)
seq_comps = [e["id"] for e in views[V3]["els"] if e["kind"] == "lifeline"]
gaps_corr = [c for c in seq_comps if not any(e["id"] == c for v in (V1, V2) for e in views[v]["els"])]
viewset = {"system": "Progetto-IS-main-English", "stakeholder": "tester", "goal": profile["goal"], "views": vs_views, "correspondences": corr,
           "correspondence_gaps": gaps_corr, "declared_gaps": [], "uncovered_needs": plan["uncovered_needs"], "secondary_not_shown": plan["secondary_not_shown"]}
dump(OUT + "/viewset.json", viewset)

# traceability.md
T = ["# Traceability", ""]
for v in vs_views:
    T += [f"## {v['id']}", "", "| Element | Files | Symbols |", "|---|---|---|"]
    for t in v["traceability"]:
        T.append(f"| {t['name']} | {'<br>'.join(t['files'])} | {'<br>'.join(t['symbols']) or '—'} |")
    T.append("")
open(OUT + "/traceability.md", "w").write("\n".join(T))

# README
nclaims, nrej = len(claims), len(model["rejected_claims"])
byk = {}
for c in claims.values():
    byk[c["kind"]] = byk.get(c["kind"], 0) + 1
sup = {}
for c in claims.values():
    sup[c["support"]] = sup.get(c["support"], 0) + 1
RM = []
RM.append("# Task2View single-agent run: IS-reg-L3\n")
RM.append(f"**Goal:** {profile['goal']}\n")
RM.append("- **Role:** integration tester (`tester`)\n- **Target:** user registration functionality\n- **Detail level:** detailed (the goal enumerates 5 subjects)")
RM.append("- **Primary needs:** decomposition, dependencies, collaboration, interaction-order\n- **Secondary needs:** interface-contract (covered by V2), data-structure (not shown)")
RM.append("- **Model / condition:** Claude Sonnet 5.5 (claude-sonnet-5-5), agent + task2view skill, notation PlantUML. No usage.json: the tool does not report tokens or cost to the agent.\n")
RM.append("## Views\n\n| View | Viewpoint | Decision | Verdict | Elements | Notation |\n|---|---|---|---|---|---|")
for v in V_PROP:
    n = len([e for e in views[v]["els"] if not e["group"]])
    RM.append(f"| {v} | {V_PROP[v][0]} | {recon[v]['decision']} | {report[v]['verdict']} | {n} | PlantUML (`{v}/view.puml`, compile check: {report[v]['notation']['status']}) |")
RM.append("\n## Rationale\n")
for pv in plan["views"]:
    RM.append(f"- **{pv['viewpoint_id']}**: {pv['rationale']}.")
RM.append("\nOrder of views follows the first primary need each covers: structure and responsibilities (V1), collaboration and dependencies (V2), failure and alternative paths (V3).\n")
RM.append("## Limitations and declared gaps\n")
for v in V_PROP:
    for l in views[v]["limitations"]:
        RM.append(f"- ({v}) {l}")
RM.append("- Declared gaps: none. Uncovered primary needs: none. Secondary need not shown: data-structure (no data-model view was selected; role-specific fields appear only as responsibilities of Student and Librarian).")
RM.append("- The 15-element cap is counted on non-group elements; layer groups are not counted. If groups were counted, V1 and V2 would exceed the cap (4 + 14 and 4 + 15).")
RM.append("- Task fit (layer 5) is `not-run`: a different model must judge.")
RM.append("- Source comments in the repository were replaced by a placeholder, so responsibilities come from names, validations and calls, not from documentation.")
RM.append("\n## Evidence counts\n")
RM.append(f"- Claims: {nclaims} verified, {nrej} rejected ({', '.join(f'{k}: {n}' for k, n in byk.items())}); support: {', '.join(f'{k}: {n}' for k, n in sup.items())}")
