    RM.append(f"- **{pv['viewpoint_id']}**: {pv['rationale']}.")
RM.append("\nOrder of views follows the first primary need each covers: structure and responsibilities (V1), collaboration and dependencies (V2), failure and alternative paths (V3).\n")
RM.append("## Limitations and declared gaps\n")
for v in V_PROP:
    for l in views[v]["limitations"]:
        RM.append(f"- ({v}) {l}")
RM.append("- Declared gaps: none. Uncovered primary needs: none. Secondary need not shown: data-structure (no data-model view was selected; role-specific fields appear only as responsibilities of Student and Librarian).")
RM.append("- The 15-element cap is counted on non-group elements; layer groups are not counted. If groups were counted, V1 and V2 would exceed the cap (4 + 14 and 4 + 15).")
RM.append("- Task fit (layer 5) is `not-run`: a different model must judge.")
RM.append("- Source comments in the repository were replaced by a placeholder, so responsibilities come from names, validations and calls, not from documentation.")
RM.append("\n## Evidence counts\n")
RM.append(f"- Claims: {nclaims} verified, {nrej} rejected ({', '.join(f'{k}: {n}' for k, n in byk.items())}); support: {', '.join(f'{k}: {n}' for k, n in sup.items())}")
RM.append(f"- Evidence model: {len(elements)} elements, {len(relations)} relations (incl. {sum(1 for r in relations.values() if r['kind']=='is-part-of')} derived is-part-of), 1 scenario with {len(steps)} steps and {len(model['scenarios']['scn:register-user']['fragments'])} alt fragments")
RM.append("- Reflexion: all claimed relations converge with code edges; no divergence or absence recorded.")
open(OUT + "/README.md", "w").write("\n".join(RM) + "\n")
print("recon:", {v: r["decision"] for v, r in recon.items()})
print("verdicts:", {v: (r["verdict"], r["errors"], r["warnings"], r["notation"]["status"], r["notation"]["compiler_output"]) for v, r in report.items()})
print("cov:", {v: [c["status"] for c in cover[v]] for v in cover})
print("corr gaps", gaps_corr)

